typedef enum {
    NL_RPC_PAYLOAD_NONE = 0,
    NL_RPC_PAYLOAD_TEXT = 1,
    NL_RPC_PAYLOAD_BINARY = 2,
    NL_RPC_PAYLOAD_PATH_VALUE = 3,
} nl_rpc_payload_format;

typedef enum {
    NL_RPC_ACCESS_INTERNAL = 0,
    NL_RPC_ACCESS_VIEW,
    NL_RPC_ACCESS_CONFIG,
    NL_RPC_ACCESS_COMMIT,
    NL_RPC_ACCESS_CLEAR,
    NL_RPC_ACCESS_ADMIN,
} nl_rpc_access;

#define NL_RPC_CONTRACT_TX_ID_REQUIRED (1U << 0)
#define NL_RPC_CONTRACT_MGMT_EXPOSED   (1U << 1)

typedef struct {
    nl_daemon_id service;
    nl_rpc_method method;
    const char *name;
    nl_rpc_payload_format request_format;
    nl_rpc_payload_format response_format;
    u32 max_request_len;
    u32 max_response_len;
    u64 caller_mask;
    u32 flags;
    nl_rpc_access access;
    bool internal_authority_allowed;
} nl_rpc_contract;

const nl_rpc_contract *nl_rpc_contract_lookup(nl_daemon_id service,
                                              nl_rpc_method method);
size_t nl_rpc_contract_count(void);
const nl_rpc_contract *nl_rpc_contract_at(size_t index);
bool nl_rpc_contract_caller_allowed(const nl_rpc_contract *contract,
                                    nl_daemon_id caller);
bool nl_rpc_contract_payload_valid(nl_rpc_payload_format format,
                                   const u8 *payload, u32 payload_len,
                                   u32 max_payload_len);
const char *nl_rpc_access_name(nl_rpc_access access);

